SELECT CASE WHEN m.entry_quality_score < 50 THEN '<50' WHEN m.entry_quality_score = 50 THEN '=50' WHEN m.entry_quality_score < 55 THEN '51-54' WHEN m.entry_quality_score < 70 THEN '55-69' WHEN m.entry_quality_score < 85 THEN '70-84' ELSE '85+' END AS eq_bucket, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, SUM(p.realized_pnl>0) AS wins, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_ret_pct FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.status='CLOSED' AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY eq_bucket ORDER BY eq_bucket LIMIT 10;
SELECT eo.decision_code, m.entry_quality_score, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=p.signal_id JOIN crypto_ai.execution_opportunity eo ON eo.latest_signal_id=p.signal_id AND eo.status='EXECUTED' WHERE p.status='CLOSED' AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) AND eo.decision_code IN ('BALANCED_NEUTRAL_5M_WATCH_1H','FRESH_5M_CONFIRMATION','OPPORTUNITY_CONFIRMED') GROUP BY eo.decision_code, m.entry_quality_score ORDER BY eo.decision_code, m.entry_quality_score LIMIT 60;